INSERT INTO files (code, full_code, title, tags, inventory_id)
SELECT mf.code, 'ДАС' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code, mf.title, mf.tags, i.id
FROM mf JOIN fonds fo ON fo.code = mf.fond JOIN arch ON arch.id = fo.archive_id JOIN inventories i ON i.fond_id = fo.id AND i.code = mf.inv
WHERE NOT EXISTS (SELECT 1 FROM files x WHERE x.inventory_id = i.id AND x.code = mf.code);
INSERT INTO file_years (file_id, start_year, end_year) SELECT f.id, split_part(r, '-', 1)::int, split_part(r, '-', 2)::int
FROM mf JOIN files f ON f.full_code = 'ДАС' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code, unnest(string_to_array(mf.years, ',')) r
WHERE mf.years <> '' AND NOT EXISTS (SELECT 1 FROM file_years y WHERE y.file_id = f.id) ON CONFLICT DO NOTHING;
DO $$ BEGIN IF (SELECT count(*) FROM mf JOIN files f ON f.full_code = 'ДАС' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code) <> (SELECT count(*) FROM mf) THEN RAISE EXCEPTION 'A: not all files created (inventory missing?)'; END IF; END $$;

-- H. year ranges: DB span is a strict subset of the catalog's → catalog ranges
CREATE TEMP TABLE hy(full_code text, old text, new text); INSERT INTO hy VALUES ('ДАС-30-1-36','1896-1896','1843-1843,1896-1896');
CREATE TEMP TABLE hf AS SELECT hy.*, f.id AS file_id FROM hy JOIN files f ON f.full_code = hy.full_code;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM hf WHERE (SELECT min(start_year)||'-'||max(end_year) FROM file_years y WHERE y.file_id = hf.file_id) IS DISTINCT FROM hf.old) THEN RAISE EXCEPTION 'H: DB years changed since snapshot'; END IF; END $$;
DELETE FROM file_years y USING hf WHERE y.file_id = hf.file_id; INSERT INTO file_years (file_id, start_year, end_year) SELECT hf.file_id, split_part(r, '-', 1)::int, split_part(r, '-', 2)::int FROM hf, unnest(string_to_array(hf.new, ',')) r;

